class Registry { private map = new Map<string, () => FamilyFactory>(); register(name: string, ctor: () => FamilyFactory){ this.map.set(name, ctor) } getFactory(name: string): FamilyFactory { const ctor = this.map.get(name); if(!ctor) throw new Error('Unknown tenant'); return ctor(); } }
